package app.codeg.android.feature.main

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.compose.ui.window.Dialog
import androidx.compose.ui.window.DialogProperties
import app.codeg.android.core.designsystem.theme.CodegTheme
import app.codeg.android.core.network.RovaiOperation
import kotlinx.coroutines.*
import kotlinx.serialization.json.*
import java.util.UUID

/** Native ProjectGroupsDialog. A frozen full-value CAS survives unknown replies; no project access is granted. */
@Composable fun RovaiProjectGroups(model:RovaiWorkspaceViewModel,onClose:()->Unit){
    val state=model.state.collectAsState().value;val scope=rememberCoroutineScope();val generation=remember{model.connectionGeneration};val draftOwner="project-groups:editor";val pendingOwner="project-groups:pending"
    var source by remember{mutableStateOf<JsonObject?>(null)};var editor by remember{mutableStateOf<JsonObject?>(null)};var pending by remember{mutableStateOf<JsonObject?>(null)};var folders by remember{mutableStateOf<Map<String,RovaiCanvasFolderRelation>>(emptyMap())};var busy by remember{mutableStateOf(false)};var ready by remember{mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var removal by remember{mutableStateOf<JsonObject?>(null)};var useCurrent by remember{mutableStateOf(false)}
    val active=state.navigation["projects"].coreArray().map{it.coreText("projectPath")}.filter(::rovaiProjectPath).distinct();val groups=source?.get("projectGroups").coreArray();val currentRevision=source?.coreLong("projectGroupsRevision")?:0;val stale=editor!=null&&editor?.coreLong("revision")!=currentRevision;val blocked=busy||!ready||source==null||pending!=null||state.busy||state.pending!=null||generation!=model.connectionGeneration
    fun editorBody(value:JsonObject)=buildJsonObject{put("version",1);put("editor",value)}.toString()
    fun change(patch:Map<String,JsonElement>){val previous=editor?:return;val next=JsonObject(previous+patch);editor=next;if(ready&&generation==model.connectionGeneration)model.rememberBody(draftOwner,editorBody(next))}
    suspend fun load(){val value=readProjectGroups(model);val paths=(active+(editor?.get("group").coreObject()["projectPaths"]as?JsonArray)?.mapNotNull{(it as?JsonPrimitive)?.contentOrNull}.orEmpty()).distinct();val related=readCanvasFolderRelations(model,paths);require(generation==model.connectionGeneration);source=value;folders=related}
    suspend fun finish(value:JsonObject,record:JsonObject){val params=record["params"].coreObject();require(projectGroupPendingMatches(value,params)){"当前分组与原修改尚未一致；保留原请求核对"};require(model.clearBodyIfMatches(pendingOwner,record.toString(),generation)){"本机未决记录已有新修改，已保留"};val previous=(record["editorBody"]as?JsonPrimitive)?.contentOrNull;if(previous!=null)model.clearBodyIfMatches(draftOwner,previous,generation);require(generation==model.connectionGeneration);source=value;pending=null;editor=null;issue=null}
    suspend fun send(record:JsonObject){val params=record["params"].coreObject();val value=parseProjectGroups(model.query(RovaiOperation.NAVIGATION_PROJECTGROUPS,params));require(generation==model.connectionGeneration);finish(value,record)}
    fun apply(mutation:JsonObject){if(blocked||stale)return;val current=source?:return;busy=true;scope.launch{try{
        val revision=editor?.coreLong("revision")?:current.coreLong("projectGroupsRevision");val value=projectGroupPlan(current,revision,mutation,active);val params=buildJsonObject{put("action","replace");put("expectedRevision",revision);put("value",value)}
        val record=buildJsonObject{put("version",1);put("params",params);put("editorBody",editor?.let{JsonPrimitive(editorBody(it))}?:JsonNull)};model.saveBody(pendingOwner,record.toString());model.rememberBody(pendingOwner,record.toString());require(generation==model.connectionGeneration);pending=record;send(record)
    }catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}}
    fun refresh(){if(busy)return;busy=true;scope.launch{try{load();val record=pending;if(record!=null&&source?.let{projectGroupPendingMatches(it,record["params"].coreObject())}==true)finish(source!!,record)}catch(error:Exception){issue=error.message}finally{busy=false}}}
    fun edit(row:JsonObject?){if(blocked)return;val group=row?:buildJsonObject{put("id",UUID.randomUUID().toString());put("name","");put("color",JsonNull);put("projectPaths",JsonArray(emptyList()))};val value=buildJsonObject{put("mode",if(row==null)"create"else"update");put("revision",currentRevision);put("group",group)};editor=value;model.rememberBody(draftOwner,editorBody(value))}
    fun groupChange(patch:Map<String,JsonElement>){val group=editor?.get("group").coreObject();change(mapOf("group" to JsonObject(group+patch)))}
    fun close(){if(busy)return;val value=editor;if(!ready||value==null||generation!=model.connectionGeneration){onClose();return};scope.launch{try{val body=editorBody(value);model.saveBody(draftOwner,body);model.rememberBody(draftOwner,body);onClose()}catch(error:Exception){issue=error.message}}}
    LaunchedEffect(generation){busy=true;try{val rawPending=model.readBody(pendingOwner);if(rawPending.isNotEmpty()){val value=Json.parseToJsonElement(rawPending).coreObject();val params=value["params"].coreObject();require(value["version"]==JsonPrimitive(1)&&params.coreText("action")=="replace"&&params["value"]is JsonObject&&params["expectedRevision"]is JsonPrimitive){"原分组未决记录无法读取，已保留"};pending=value};val raw=model.readBody(draftOwner);if(raw.isNotEmpty()){val value=Json.parseToJsonElement(raw).coreObject();require(value["version"]==JsonPrimitive(1)&&value["editor"]is JsonObject){"原分组草稿无法读取，已保留"};editor=value["editor"].coreObject()};load();ready=true}catch(error:Exception){issue=error.message}finally{busy=false}}
    val group=editor?.get("group").coreObject();val selected=(group["projectPaths"]as?JsonArray)?.mapNotNull{(it as?JsonPrimitive)?.contentOrNull}.orEmpty();val previous=groups.firstOrNull{it.coreText("id")==group.coreText("id")};val previousPaths=(previous?.get("projectPaths")as?JsonArray)?.mapNotNull{(it as?JsonPrimitive)?.contentOrNull}.orEmpty();val membershipIssue=selected.any{it !in previousPaths&&(folders[it]?.complete!=true||folders[it]?.parentPath!=null)};val missing=editor?.coreText("mode")=="update"&&previous==null
    Dialog(onDismissRequest={close()},properties=DialogProperties(usePlatformDefaultWidth=false,dismissOnClickOutside=false)){Surface(Modifier.fillMaxSize(),color=CodegTheme.colors.bgElevated){Column{
        Row(Modifier.fillMaxWidth().padding(12.dp)){Text("管理项目分组",Modifier.weight(1f),style=MaterialTheme.typography.titleMedium);TextButton(enabled=!busy,onClick={close()}){Text("保留草稿并关闭")}}
        LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
            item{Text("分组由当前工作区共享，文件和对话保持原处。",color=CodegTheme.colors.textSecondary);if(busy)LinearProgressIndicator(Modifier.fillMaxWidth());issue?.let{Text(it,color=CodegTheme.colors.danger)};TextButton(enabled=!busy,onClick={refresh()}){Text("重新读取分组")}}
            pending?.let{record->val params=record["params"].coreObject();item{Text("原分组修改待核对，不会自动重发。",color=CodegTheme.colors.danger);TextButton(enabled=!busy,onClick={busy=true;scope.launch{try{send(record)}catch(error:Exception){issue=error.message}finally{busy=false}}}){Text("原样重试原修改")};if(source!=null&&currentRevision>params.coreLong("expectedRevision"))TextButton(enabled=!busy,onClick={useCurrent=true}){Text("使用当前版本并放弃旧本机计划")}}}
            if(editor==null){item{TextButton(enabled=!blocked,onClick={edit(null)}){Text("新建项目分组")}};if(groups.isEmpty())item{Text("还没有项目分组。",color=CodegTheme.colors.textSecondary)};groups.forEach{row->item(key=row.coreText("id")){Text(row.coreText("name"),style=MaterialTheme.typography.titleSmall);Text("${(row["projectPaths"]as?JsonArray)?.size?:0} 个工程",color=CodegTheme.colors.textSecondary);Row{TextButton(enabled=!blocked,onClick={edit(row)}){Text("编辑")};TextButton(enabled=!blocked,onClick={removal=buildJsonObject{put("group",row);put("revision",currentRevision)}}){Text("删除",color=CodegTheme.colors.danger)}}}}}
            else{
                item{if(stale){Text("分组已有新修改，输入已保留。请核对最新清单后继续。",color=CodegTheme.colors.danger);groups.forEach{Text(it.coreText("name")+" · "+((it["projectPaths"]as?JsonArray)?.size?:0)+" 个工程",style=MaterialTheme.typography.bodySmall)};TextButton(enabled=!blocked&&!missing,onClick={change(mapOf("revision" to JsonPrimitive(currentRevision)))}){Text("已核对最新分组")}};if(missing)Text("原分组已移除，不能用旧输入重新创建。",color=CodegTheme.colors.danger)
                    OutlinedTextField(group.coreText("name"),{groupChange(mapOf("name" to JsonPrimitive(it)))},Modifier.fillMaxWidth(),label={Text("分组名称")},enabled=!blocked);RovaiCanvasChoice("分组颜色",group.coreText("color"),rovaiCanvasColors,!blocked){groupChange(mapOf("color" to if(it.isEmpty())JsonNull else JsonPrimitive(it)))}
                    if(membershipIssue)Text("所选新工程的工作树关系尚未核对，或此工作树跟随主工程；暂不能新增关联。",color=CodegTheme.colors.danger)
                }
                (active+selected).distinct().forEach{path->item(key=path){val checked=path in selected;val parent=folders[path]?.parentPath;Row{Checkbox(checked,enabled=!blocked&&(checked||path in active&&parent==null),onCheckedChange={value->groupChange(mapOf("projectPaths" to JsonArray((if(value)selected+path else selected-path).map(::JsonPrimitive))))});Column(Modifier.weight(1f)){Text(path,style=MaterialTheme.typography.bodySmall);val owner=groups.firstOrNull{it.coreText("id")!=group.coreText("id")&&(it["projectPaths"]as?JsonArray)?.contains(JsonPrimitive(path))==true};if(owner!=null&&parent==null)Text("当前属于“${owner.coreText("name")}”，保存后移入本组。",color=CodegTheme.colors.textSecondary,style=MaterialTheme.typography.labelSmall);if(path !in active)Text("工程已移除，原关联保留；取消勾选会明确移出。",color=CodegTheme.colors.textSecondary);if(parent!=null)Text("此工作树跟随主工程归组。",color=CodegTheme.colors.textSecondary)}}}}
                item{val name=group.coreText("name").trim();Button(enabled=!blocked&&!stale&&!missing&&!membershipIssue&&name.isNotEmpty()&&name.codePointCount(0,name.length)<=80,onClick={apply(buildJsonObject{put("type",editor!!.coreText("mode"));put("group",group)})}){Text("保存分组")};TextButton(enabled=!blocked,onClick={val old=editor?:return@TextButton;busy=true;scope.launch{try{require(model.clearBodyIfMatches(draftOwner,editorBody(old),generation)){"草稿已有新修改，已保留"};editor=null}catch(error:Exception){issue=error.message}finally{busy=false}}}){Text("放弃草稿，返回清单")}}
            }
        }
    }}}
    removal?.let{value->val row=value["group"].coreObject();AlertDialog(onDismissRequest={removal=null},title={Text("删除分组“${row.coreText("name")}”？")},text={Text("工程将回到顶层，文件、使命和对话都会保留。")},confirmButton={TextButton(enabled=!blocked&&value.coreLong("revision")==currentRevision,onClick={apply(buildJsonObject{put("type","delete");put("groupId",row.coreText("id"))});removal=null}){Text("确认删除分组")}},dismissButton={TextButton(onClick={removal=null}){Text("取消")}})}
    if(useCurrent)AlertDialog(onDismissRequest={useCurrent=false},title={Text("使用当前分组版本？")},text={Text("当前版本已超过原修改的版本，原旧请求不能再写入。只放弃这次本机未决计划；未保存的分组草稿仍保留。")},confirmButton={TextButton(enabled=!busy,onClick={val record=pending?:return@TextButton;busy=true;scope.launch{try{load();require(source!!.coreLong("projectGroupsRevision")>record["params"].coreObject().coreLong("expectedRevision")){"原修改仍可能生效，请继续核对"};require(model.clearBodyIfMatches(pendingOwner,record.toString(),generation)){"本机记录已变化，已保留"};pending=null;useCurrent=false}catch(error:Exception){issue=error.message}finally{busy=false}}}){Text("使用当前版本")}},dismissButton={TextButton(onClick={useCurrent=false}){Text("保留原计划")}})
}
